// Snapshot of artist names with generated comparison images in the public NAX
// “Danbooru Artist Tags 2 · V5” gallery. Preview images remain remote and are
// fetched only after an explicit user action.
export const NAX_V5_GALLERY_URL = 'https://nax.moe/?gallery=danbooru-artist-tags-2-v5';

// NAX keeps the gallery filter in the URL, so an author link can open the
// matching result directly instead of making the user type the tag again.
export function buildNaxV5ArtistSearchUrl(value) {
  const url = new URL(NAX_V5_GALLERY_URL);
  const normalized = normalizeArtistIdentity(value);
  if (!normalized) return url.toString();
  url.searchParams.set('page', '1');
  url.searchParams.set('search', normalized);
  return url.toString();
}

