export const NAX_V5_ARTISTS = Object.freeze([...NAX_V5_ARTISTS_BASE, ...NAX_V5_ARTISTS_2026_08_28, ...NAX_V5_ARTISTS_2026_09_12, ...NAX_V5_ARTISTS_2026_09_22]);

const NAX_V5_ARTIST_SET = new Set(NAX_V5_ARTISTS.map(normalizeArtistIdentity));

export function normalizeArtistIdentity(value) {
  return String(value ?? '')
    .trim()
    .replace(/^artist\s*:\s*/i, '')
    .replace(/\\([()])/g, '$1')
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .toLocaleLowerCase('en-US');
}

export function isNaxV5Artist(value) {
  const normalized = normalizeArtistIdentity(value);
  return Boolean(normalized && NAX_V5_ARTIST_SET.has(normalized));
}

// Installable roster/alias index. NAX_V5_ARTIST_SET stays the gallery snapshot;
// this map is the owner's library plus unique aliases, loaded from the database.
// Ambiguous aliases are dropped: guessing would classify the wrong person.

let rosterCanonicalByKey = new Map();
let uniqueAliasCanonicalByKey = new Map();

export function resetArtistIdentityIndex() {
  rosterCanonicalByKey = new Map();
  uniqueAliasCanonicalByKey = new Map();
}

export function installArtistIdentityIndex(input = {}) {
  resetArtistIdentityIndex();
  const names = Array.isArray(input?.names) ? input.names : [];
  const aliases = Array.isArray(input?.aliases) ? input.aliases : [];
  for (const name of names) {
    const canonical = String(name ?? '').trim();
    const key = normalizeArtistIdentity(canonical);
    if (!key || rosterCanonicalByKey.has(key)) continue;
    rosterCanonicalByKey.set(key, canonical);
  }
  const aliasOwners = new Map();
  for (const pair of aliases) {
    if (!Array.isArray(pair) || pair.length < 2) continue;
    const aliasKey = normalizeArtistIdentity(pair[0]);
    const owner = String(pair[1] ?? '').trim();
    const ownerKey = normalizeArtistIdentity(owner);
    if (!aliasKey || !ownerKey) continue;
    if (rosterCanonicalByKey.has(aliasKey)) continue;
    const canonical = rosterCanonicalByKey.get(ownerKey) || owner;
    if (!aliasOwners.has(aliasKey)) aliasOwners.set(aliasKey, new Set());
    aliasOwners.get(aliasKey).add(canonical);
  }
  for (const [key, owners] of aliasOwners) {
    if (owners.size !== 1) continue;
    uniqueAliasCanonicalByKey.set(key, owners.values().next().value);
  }
}

export function identifyArtistTag(value, overrides = null) {
  const literal = String(value ?? '').trim();
  const explicit = /^artist\s*:\s*\S+/i.test(literal);
  const normalized = normalizeArtistIdentity(literal);
  const override = overrides && Object.prototype.hasOwnProperty.call(overrides, normalized)
    ? overrides[normalized]
    : null;
  const indexed = isNaxV5Artist(normalized);
  const rosterName = rosterCanonicalByKey.get(normalized) || '';
  const aliasName = uniqueAliasCanonicalByKey.get(normalized) || '';
  const canonical = rosterName || aliasName;
  const recognized = explicit || override === true || (override !== false && (indexed || Boolean(canonical)));
  const source = explicit ? 'explicit'
    : override === true ? 'override'
    : indexed ? 'nax-v5'
    : rosterName ? 'roster'
    : aliasName ? 'alias'
    : '';
  return {
    literal,
    name: literal.replace(/^artist\s*:\s*/i, '').trim(),
    normalized,
    explicit,
    indexed,
    recognized,
    source,
    canonical
  };
}

// Artist name check (1.9.2, owner 2026-10-22): tags from elsewhere often carry misspelled
// artist names, which NovelAI silently ignores. A name is known when the NAX V5 index, the
// library roster or a unique alias has it; for an unknown name, the closest known names are
// offered (edit distance, plus the bare form of "name (alias)" entries).

export function isKnownArtistName(value) {
  const key = normalizeArtistIdentity(value);
  return Boolean(key && (NAX_V5_ARTIST_SET.has(key) || rosterCanonicalByKey.has(key) || uniqueAliasCanonicalByKey.has(key)));
}

// Optimal string alignment distance with an early exit once every cell exceeds `limit`.
function artistNameDistance(a, b, limit) {
  if (Math.abs(a.length - b.length) > limit) return limit + 1;
  let previous2 = null, previous = Array.from({ length: b.length + 1 }, (_, index) => index);
  for (let i = 1; i <= a.length; i++) {
    const current = [i];
    let best = current[0];
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      let value = Math.min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost);
      if (previous2 && i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) value = Math.min(value, previous2[j - 2] + 1);
      current[j] = value;
      if (value < best) best = value;
    }
    if (best > limit) return limit + 1;
    previous2 = previous; previous = current;
  }
  return previous[b.length];
}

const compactArtistKey = key => key.replace(/[^\p{L}\p{N}]+/gu, '');

export function suggestArtistNames(value, limit = 3) {
  const key = normalizeArtistIdentity(value);
  if (key.length < 3) return [];
  const allowed = key.length <= 5 ? 1 : key.length <= 10 ? 2 : 3;
  const compact = compactArtistKey(key);
  const candidates = new Map();
  for (const name of NAX_V5_ARTISTS) candidates.set(normalizeArtistIdentity(name), name);
  for (const [candidateKey, name] of rosterCanonicalByKey) candidates.set(candidateKey, name);
  for (const [candidateKey, name] of uniqueAliasCanonicalByKey) if (!candidates.has(candidateKey)) candidates.set(candidateKey, name);
  const found = new Map();
  for (const [candidateKey, name] of candidates) {
    if (candidateKey === key) continue;
    // "hitenkei" for "hiten (hitenkei)", or the same letters without spaces / punctuation.
    const parts = /^(.*?)\s*\(([^()]+)\)\s*$/.exec(candidateKey);
    const base = parts?.[1]?.trim(), parenthesized = parts?.[2]?.trim();
    let distance = compactArtistKey(candidateKey) === compact || parenthesized === key || base === key ? 0 : artistNameDistance(key, candidateKey, allowed);
    for (const part of [base, parenthesized]) if (distance > allowed && part && part.length >= 3) distance = Math.min(distance, artistNameDistance(key, part, allowed));
    if (distance > allowed) continue;
    const display = String(name);
    const previous = found.get(normalizeArtistIdentity(display));
    if (!previous || distance < previous.distance) found.set(normalizeArtistIdentity(display), { name: display, distance });
  }
  return [...found.values()].sort((left, right) => left.distance - right.distance || left.name.length - right.name.length || left.name.localeCompare(right.name)).slice(0, limit);
}

// 画师库「加入画风」按人去重，不按权重。`1.2::artist:anmi::` 和裸 `artist:anmi` 是同一个人。

export function sameArtistIdentity(left, right, overrides = null) {
  const a = identifyArtistTag(left, overrides);
  const b = identifyArtistTag(right, overrides);
  if (!a.recognized || !b.recognized) return false;
  const leftKey = normalizeArtistIdentity(a.canonical || a.normalized);
  const rightKey = normalizeArtistIdentity(b.canonical || b.normalized);
  return Boolean(leftKey && leftKey === rightKey);
}

// New tags, 拆条, and structured import write this prefix. Restoring a stored
// scheme must keep the saved spelling — hydrateTag / normalizeStoredState never
// call this.

export function applyArtistPrefixToTagText(value, overrides = null) {
  const literal = String(value ?? '').trim();
  if (!literal) return literal;
  const identity = identifyArtistTag(literal, overrides);
  if (!identity.recognized || identity.explicit) return literal;
  const name = String(identity.canonical || identity.name || '').trim();
  return name ? `artist:${name}` : literal;
}
